        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge rounded-pill @BadgeClass fs-6">@AlertService.LatestAlertCount</span>
        </p>
        <p class="text-muted small mb-0">
            Polling every 10 seconds. Last refresh: @_lastRefresh.ToString("T")
        </p>
    </div>
</div>

@code {
    private DateTime _lastRefresh = DateTime.Now;

    private string BadgeClass =>
        AlertService.LatestAlertCount > 0 ? "text-bg-danger" : "text-bg-success";

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += RefreshAsync;
        AlertService.OnAlertCountChanged += OnAlertDataAsync;

        // Start polling when the dashboard is visible.
        AlertService.StartPolling();
    }

    private async Task RefreshAsync()
    {
        await InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertDataAsync()
    {
        _lastRefresh = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= RefreshAsync;
        AlertService.OnAlertCountChanged -= OnAlertDataAsync;

        // Stop polling when the user leaves the dashboard.
        AlertService.StopPolling();
    }
}

